// Validate input from Phase 3b
const videoData = $input.first().json;

// Validate required fields
if (!videoData.long_form_video || !videoData.long_form_video.url) {
  throw new Error('Missing long-form video URL');
}

if (!videoData.script_id || typeof videoData.script_id !== 'string') {
  throw new Error('Missing or invalid script_id');
}

if (!videoData.title || typeof videoData.title !== 'string' || videoData.title.length < 5) {
  throw new Error('Title must be at least 5 characters');
}

if (!videoData.description || typeof videoData.description !== 'string') {
  throw new Error('Missing description');
}

if (!Array.isArray(videoData.tags) || videoData.tags.length === 0) {
  throw new Error('At least 1 tag required');
}

if (!videoData.category_id || typeof videoData.category_id !== 'string') {
  throw new Error('Missing category_id (YouTube category)');
}

// Validate title length (YouTube: 1-100 characters)
if (videoData.title.length > 100) {
  throw new Error('Title exceeds 100 characters');
}

// Validate description length (YouTube: 0-5000 characters)
if (videoData.description.length > 5000) {
  throw new Error('Description exceeds 5000 characters');
}

// Validate tags (max 30, each max 30 chars)
if (videoData.tags.length > 30) {
  throw new Error('Maximum 30 tags allowed');
}

for (const tag of videoData.tags) {
  if (tag.length > 30) {
    throw new Error(`Tag "${tag}" exceeds 30 characters`);
  }
}

// Validate privacy status (default to private)
const validPrivacyStatuses = ['private', 'unlisted', 'public'];
const privacyStatus = videoData.privacy_status || 'private';
if (!validPrivacyStatuses.includes(privacyStatus)) {
  throw new Error(`Invalid privacy_status: ${privacyStatus}. Must be: ${validPrivacyStatuses.join(', ')}`);
}

// Validate video format (must be .mp4)
if (!videoData.long_form_video.url.endsWith('.mp4')) {
  throw new Error('Only MP4 format supported');
}

// Validate video duration (minimum 5 seconds, maximum 12 hours)
const durationSeconds = videoData.long_form_video.duration_seconds || 0;
if (durationSeconds < 5) {
  throw new Error('Video too short (minimum 5 seconds)');
}
if (durationSeconds > 43200) {
  throw new Error('Video too long (maximum 12 hours)');
}

return {
  ...videoData,
  privacy_status: privacyStatus,
  validation_status: 'passed',
  validated_at: new Date().toISOString(),
  validation_errors: []
};

// Check for duplicate uploads using script_id metadata
const videoData = $input.first().json;
const scriptId = videoData.script_id;

// Query stored upload history (simulated - in production, query real database)
const uploadHistory = {
  // Check if script_id already uploaded
  [scriptId]: null  // null = not uploaded yet
};

const existingUpload = uploadHistory[scriptId];

if (existingUpload) {
  return {
    script_id: scriptId,
    is_duplicate: true,
    existing_youtube_id: existingUpload.youtube_video_id,
    existing_upload_date: existingUpload.upload_date,
    status: 'duplicate_detected',
    message: `This script was already uploaded on ${existingUpload.upload_date}`
  };
}

// Not a duplicate - proceed
return {
  script_id: scriptId,
  is_duplicate: false,
  duplicate_check_status: 'passed',
  checked_at: new Date().toISOString()
};

