// Check YouTube API quota before proceeding
// In production, query youtube.i18nLanguages.list to check real quota
const quotaData = {
  limit: 10000,
  used: 3500,
  remaining: 6500,
  reset_time: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
};

const quotaNeeded = 150; // Typical quota for upload + metadata update
const hasEnoughQuota = quotaData.remaining > quotaNeeded;

if (!hasEnoughQuota) {
  throw new Error(`Insufficient YouTube API quota. Need: ${quotaNeeded}, Available: ${quotaData.remaining}`);
}

return {
  quota: quotaData,
  quota_needed: quotaNeeded,
  sufficient_quota: true,
  quota_check_status: 'passed',
  checked_at: new Date().toISOString()
};

