// Validate approval decision
const approvalDecision = $input.first().json;

if (!approvalDecision.approval_id) {
  throw new Error('Missing approval_id');
}

if (!['approved', 'rejected', 'needs_changes'].includes(approvalDecision.decision)) {
  throw new Error(`Invalid decision: ${approvalDecision.decision}. Must be: approved, rejected, or needs_changes`);
}

if (!approvalDecision.approver) {
  throw new Error('Missing approver information');
}

return {
  ...approvalDecision,
  validated_at: new Date().toISOString(),
  validation_status: 'passed'
};

