// Extract resumable session URI from Location header
const response = $input.first();
const resumableUri = response.headers?.['location'] || response.headers?.['x-goog-upload-session-uri'];

if (!resumableUri) {
  throw new Error('Failed to obtain resumable upload session URI from YouTube');
}

return {
  resumable_uri: resumableUri,
  video_url: $node['09yt-send-approval-request'].json.video_content.video_url,
  script_id: $node['09yt-send-approval-request'].json.script_id,
  session_created_at: new Date().toISOString(),
  session_expires_at: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString()
};

// Handle upload response and extract video ID
const response = $input.first().json;

if (!response.id) {
  throw new Error('Upload failed: No video ID returned from YouTube');
}

return {
  youtube_video_id: response.id,
  script_id: $node['Process - Extract Session URI'].json.script_id,
  upload_status: 'success',
  upload_timestamp: new Date().toISOString(),
  video_status: response.status?.uploadStatus || 'unknown',
  processing_status: response.processingDetails?.processingStatus || 'processing',
  privacy_status: response.status?.privacyStatus || 'private',
  youtube_url: `https://youtube.com/watch?v=${response.id}`,
  snippet: response.snippet
};

